import java.util.Scanner;

public class Words {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        String inputStr = scanner.next();
        char[] characters = inputStr.toCharArray();
        int[] counts = new int[n];
        int totalCount = 0;
        int index = 0;
        for (int i = 0; i < n; i++) {
            counts[i] = 0;
        }
        int mode = 0;
        if (characters[0] == '_') {
            mode = 0;
        } else if (characters[0] == '(') {
            mode = 1;
        }
        for (int i = 0; i < n; i++) {
            if (mode == 0) {
                if (characters[i] == '_') {
                    index++;
                } else {
                    if (characters[i] != '(') {
                        counts[index]++;
                    } else if (characters[i] == '(') {
                        mode = 1;
                    } else if (characters[i] == ')') {
                        mode = 0;
                    }
                }
            } else {
                if (characters[i] == ')') {
                    mode = 0;
                    index++;
                } else if (i > 0) {
                    if (characters[i - 1] == '(' || characters[i - 1] == '_') {
                        if (characters[i] != '_' && characters[i] != '(') {
                            totalCount++;
                        }
                    }
                }
            }
        }
        // Bubble sort
        for (int i = 0; i < n; i++) {
            for (int j = i; j > 0; j--) {
                if (counts[j] > counts[j - 1]) {
                    int temp = counts[j];
                    counts[j] = counts[j - 1];
                    counts[j - 1] = temp;
                }
            }
        }
        System.out.println(counts[0]);
        System.out.println(totalCount);
    }
}
